Omega = sample space

Events = subsets

P = probability measure

Example: fair coin, Omega = {H, T}.

Omega = {"H", "T"}

def P(event):
    event = set(event)
    return sum(0.5 for o in event if o in Omega)

print("Omega =", Omega)
print("P({H}) =", P({"H"}))

